using System;
using UnityEngine;
namespace Veilbound.Editor {
 public static class RepeatValidation {
  static void Check(bool ok,string message){if(!ok)throw new Exception("Repeat production: "+message);}
  static Settlement Sample(){var c=Settlement.NewCamp();c.mine=1;c.blacksmith=4;c.EnsureGear();c.EnsureResearch();for(int i=0;i<c.researchRanks.Length;i++)c.researchRanks[i]=LibraryResearch.IsSlotResearch(LibraryResearch.Ids[i])?0:10;c.EnsureMineOrders();c.mineOrders.Clear();return c;}
  public static void Run(){
   var c=Sample();Check(c.AddRepeatStep(false,0,2,out _)&&c.AddRepeatStep(false,1,1,out _),"quantity steps accepted");Check(c.ProjectedMineUnits(9)==3,"projection spans repeat steps");c.Tick(540,1);Check(c.ResourceAmount(0,0)==2&&c.ResourceAmount(0,1)==1&&c.mineScheduleIndex==0&&c.mineStepCompleted==0,"mine loops after quantities complete");
   c.Tick(60,1);double remaining=c.autoMineRemainingWork;c.QueueMining(1,1,out _);c.Tick(180,1);Check(c.ResourceAmount(0,1)==2&&Math.Abs(c.autoMineRemainingWork-remaining)<1e-8,"manual orders preempt repeat without losing partial unit");
   c=JsonUtility.FromJson<Settlement>(JsonUtility.ToJson(c));c.Tick(120,1);Check(c.ResourceAmount(0,0)==3&&c.mineStepCompleted==1,"schedule and partial work resume after save");c.PauseRepeat(false);double ore=c.ResourceTotal(0);c.Tick(600,1);Check(c.ResourceTotal(0)==ore,"paused schedule produces nothing");c.PauseRepeat(false);c.Tick(180,1);Check(c.ResourceAmount(0,0)==4&&c.mineScheduleIndex==1,"paused sequence resumes its position");
   c=Sample();c.AddResource(0,0,100);c.AddResource(0,1,100);c.metalBars[0]=3;c.metalBars[1]=5;c.AddResource(0,2,4);
   Check(c.QueueBars(2,2,out _)&&c.metalBars[0]==1&&c.metalBars[1]==1&&c.ResourceAmount(0,0)==100&&c.ResourceAmount(0,1)==100,"bronze consumes only two copper bars and one tin bar per output");c.CancelSmithOrder(c.smithOrders[0].id);Check(c.metalBars[0]==3&&c.metalBars[1]==5,"bronze cancellation returns bars");
   Check(c.QueueBars(3,2,out _)&&c.metalBars[1]==1&&c.ResourceAmount(0,2)==2&&c.metalBars[0]==3,"brass consumes copper bars and zinc ore");c.CancelSmithOrder(c.smithOrders[0].id);
   c=Sample();c.AddResource(0,0,2);c.AddResource(0,1,4);c.AddRepeatStep(true,1,2,out _);c.AddRepeatStep(true,0,1,out _);c.AddRepeatStep(true,2,1,out _);double cycle=2*1.25+1+1.5;c.Tick(cycle*2/c.RefiningSpeed*60,1);Check(c.metalBars[2]==2&&c.metalBars[0]==0&&c.metalBars[1]==0&&c.barScheduleIndex==0,"refining sequence makes inputs then alloys and repeats");
   c.Tick(600,1);Check(c.metalBars[2]==2&&c.autoBarOrder==null,"unfunded current step waits without skipping or spending time as credit");c.AddResource(0,1,1);c.Tick(30/c.RefiningSpeed,1);Check(c.autoBarOrder!=null&&Math.Abs(c.autoBarOrder.remainingWork-.75)<1e-8,"new ingredients start a fresh unit");
   c.AddResource(0,0,1);Check(c.QueueBars(0,1,out _),"manual order queues during repeating work");double barWork=c.autoBarOrder.remainingWork;c.Tick(60/c.RefiningSpeed,1);Check(c.metalBars[0]==1&&Math.Abs(c.autoBarOrder.remainingWork-barWork)<1e-8,"manual bar order pauses partial repeating bar");
   c=JsonUtility.FromJson<Settlement>(JsonUtility.ToJson(c));Check(c.MoveRepeatStep(true,0,1)&&c.barScheduleIndex==1&&Math.Abs(c.autoBarOrder.remainingWork-barWork)<1e-8,"reordering preserves active step and work");double copper=c.ResourceAmount(0,1);Check(c.RemoveRepeatStep(true,1)&&c.autoBarOrder==null&&c.ResourceAmount(0,1)==copper+1,"removing current step refunds unfinished reserved ingredients");
   c=Sample();Check(!c.AddRepeatStep(false,7,1,out _)&&!c.AddRepeatStep(true,9,1,out _)&&!c.AddRepeatStep(true,0,0,out _),"research/building gates and quantity validation");for(int i=0;i<12;i++)Check(c.AddRepeatStep(false,0,1,out _),"schedule accepts twelve steps");Check(!c.AddRepeatStep(false,0,1,out _),"schedule limit enforced");
   c=Sample();c.AddRepeatStep(false,1,2,out _);c.AddRepeatStep(false,0,1,out _);c.AddRepeatStep(true,1,2,out _);c.AddRepeatStep(true,0,1,out _);c.AddRepeatStep(true,2,1,out _);var stepped=JsonUtility.FromJson<Settlement>(JsonUtility.ToJson(c));c.Tick(1800,2);for(int i=0;i<36000;i++)stepped.Tick(.05,2);
   for(int i=0;i<8;i++)Check(Math.Abs(c.ResourceAmount(0,i)-stepped.ResourceAmount(0,i))<1e-7,"ore delivery frame invariance / resource "+i+" bulk "+c.ResourceAmount(0,i)+" stepped "+stepped.ResourceAmount(0,i)+" / mine work "+c.autoMineRemainingWork+" vs "+stepped.autoMineRemainingWork+" / bar work "+c.AutoBarWork+" vs "+stepped.AutoBarWork);for(int i=0;i<WeaponRules.Count;i++)Check(Math.Abs(c.metalBars[i]-stepped.metalBars[i])<1e-7,"ore-to-alloy chain frame invariance");Check(c.barScheduleIndex==stepped.barScheduleIndex&&c.mineScheduleIndex==stepped.mineScheduleIndex&&c.barStepCompleted==stepped.barStepCompleted&&Math.Abs(c.NextBarHours-stepped.NextBarHours)<1e-7,"waiting and partial alloy times do not use ore before arrival");
   var old=new Settlement{mine=1,blacksmith=3};old.EnsureMineOrders();old.EnsureSmithOrders();Check(!old.autoMineEnabled&&!old.autoBarsEnabled&&old.mineSchedule.Count==0&&old.barSchedule.Count==0,"old saves opt in to schedules");
   old.EnsureGear();old.smithOrders.Add(new SmithWorkOrder{id=99,metal=2,quantity=1,workPerBar=1.5,remainingWork=1.5,ingredients=new[]{new ResourceCost(0,1,2),new ResourceCost(0,0,1)}});copper=old.ResourceAmount(0,1);old.CancelSmithOrder(99);Check(old.ResourceAmount(0,1)==copper+2&&old.metalBars[1]==0,"legacy queued alloys refund the original paid recipe");
   Debug.Log("VEILBOUND_REPEAT_LOGIC_PASS");
  }
 }
}
